mapper.select:
SELECT COUNT(DISTINCT f.id)
FROM fixture f
WHERE f.status = 'SCHEDULED'
  AND f.kickoff_at >= #{from}
  AND f.kickoff_at < #{until}
  AND (
    #{allTeams} = TRUE
    OR EXISTS (
      SELECT 1 FROM team_manager tm
      WHERE tm.user_id = #{userId}
        AND tm.team_id IN (f.home_team_id, f.away_team_id)
    )
  )
